function Modal({title,onClose,children,wide=false}:Any){
  const dialog=useRef<HTMLElement>(null),close=useRef(onClose);close.current=onClose;
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const node=dialog.current;const initial=node?.querySelector<HTMLElement>('input,select,textarea');(initial||node)?.focus();return()=>{if(previous?.isConnected)previous.focus();};},[]);
  const keys=(e:React.KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close.current();}else if(e.key==='Tab'){const focusable=Array.from(dialog.current?.querySelectorAll<HTMLElement>('button,a[href],input,select,textarea,[tabindex]')||[]).filter(n=>n.tabIndex>=0&&!n.hasAttribute('disabled')&&n.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(!first){e.preventDefault();dialog.current?.focus();}else if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.current)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
  return <div className="modal-shade" onClick={onClose}><section ref={dialog} tabIndex={-1} onKeyDown={keys} role="dialog" aria-modal="true" aria-label={title} className={'modal '+(wide?'wide':'')} onClick={e=>e.stopPropagation()}><header><h2>{title}</h2><button className="icon-button" aria-label="关闭" onClick={onClose}><X size={20}/></button></header>{children}</section></div>;
}

